JB.kitx=[["The largest drum in a standard kit, played with a foot pedal, is…", "The bass (kick) drum", ["The floor tom", "The snare", "The rack tom"], "It gives the low thump."], ["The drum with wires stretched across its bottom head is…", "The snare drum", ["The floor tom", "The kick drum", "The rack tom"], "The wires give its crisp buzz."], ["A floor tom usually stands…", "On its own legs on the floor", ["On a cymbal stand", "Inside the kick drum", "On the snare stand"], "The lowest tom, to the drummer’s side."], ["A standard “five-piece” kit has…", "Kick, snare and three toms (plus cymbals)", ["Five cymbals", "Five snares", "Only five drumsticks"], "Cymbals aren’t counted in the number."], ["The ride cymbal is usually used for…", "Keeping time with a steady pattern", ["Only big accents", "Muting drums", "Tuning"], "It has a clear ping and a long wash."], ["A crash cymbal is mostly used for…", "Accents and marking new sections", ["Steady time keeping", "Ghost notes", "Tuning toms"], "A burst of sound, often with the kick."], ["The “bell” of the ride cymbal is…", "The raised centre, which gives a clear, cutting ping", ["The edge", "The stand", "A separate cymbal"], "Great for accents and Latin patterns."], ["A splash cymbal is…", "A small, quick crash", ["A large ride", "A hi-hat", "A gong"], "Short and bright."], ["A china cymbal sounds…", "Trashy and aggressive", ["Soft and dark", "Like a bell", "Like a snare"], "Its upturned edge gives a harsh crash."], ["Most right-handed drummers play the kick with…", "The right foot", ["The left foot", "The left hand", "A stick"], "The left foot works the hi-hat pedal."], ["A drum throne is…", "The drummer’s seat", ["A large cymbal", "A type of stick", "The bass drum hoop"], "Height and distance matter for comfort."], ["Drum sticks marked 5A are…", "A common medium weight for most styles", ["Brushes", "Mallets for timpani", "Bass drum beaters"], "7A is lighter, 2B and 5B heavier."], ["Mallets on cymbals are used for…", "Soft swells without a sharp attack", ["Loud backbeats", "Muting", "Tuning"], "Roll on a cymbal for a rising wash."], ["In a basic rock beat, the kick usually plays on…", "Beats 1 and 3", ["Beats 2 and 4", "Every sixteenth", "Never"], "The snare answers on 2 and 4."], ["In a basic rock beat, the snare plays on…", "Beats 2 and 4", ["Beats 1 and 3", "Every beat", "Only beat 1"], "The backbeat."]];if(JT.kit&&!JT.kit[2].some(x=>x[0]==='b:kitx'))JT.kit[2].push(['b:kitx',1]);


