(()=>{const A={"kitx": [["A cowbell on a drum kit is usually mounted…", "On a clamp near the kick or toms", ["Inside the snare", "On the drummer’s stool", "On the floor tom head"], "Played with the stick shoulder."], ["A “double pedal” lets you…", "Play the kick drum with both feet", ["Play two snares", "Open two hi-hats", "Tune faster"], "Common in metal."], ["The snare strainer lets you…", "Turn the snare wires on and off", ["Change the pitch", "Mute the kick", "Tilt the snare"], "Wires off makes it sound like a tom."], ["A rack tom is mounted…", "Above the kick drum or on a stand", ["On the floor", "Inside the snare", "On the hi-hat"], "Higher pitched than the floor tom."], ["A drum’s “shell” is…", "The wooden or metal body of the drum", ["The head", "The stick", "The cymbal"], "Wood type and depth change the tone."], ["A deeper snare shell usually sounds…", "Fatter and lower", ["Higher and thinner", "Exactly the same", "Like a cymbal"], "Depth adds body."], ["Electronic drum kits use…", "Pads with sensors that trigger sounds", ["Real cymbals only", "No sticks", "Strings"], "Quiet and good for practice with headphones."], ["A “rimclick” or cross-stick sound comes from…", "The stick hitting the snare rim while lying across the head", ["The kick beater", "The hi-hat pedal", "A cymbal stand"], "A woody click used in ballads."], ["Which cymbal is usually the largest on a kit?", "The ride", ["The splash", "The hi-hat", "The china (always)"], "Often 20 to 22 inches."], ["A “stack” is…", "Two cymbals placed on top of each other for a trashy, short sound", ["A pile of drums", "A drum case", "A type of roll"], "Popular in modern rock and metal."], ["The drum “head” is…", "The skin stretched over the drum", ["The cymbal", "The pedal", "The throne"], "Usually plastic (mylar) today."], ["A kick drum beater is usually made of…", "Felt, plastic or wood", ["Metal spikes", "Rubber bands", "Paper"], "Harder beaters give more attack."], ["Setting up the kit so you can reach everything without stretching helps…", "Comfort, speed and avoiding injury", ["Volume", "Tuning", "Nothing"], "Ergonomics matter."], ["Which cymbal would you choose for a gentle jazz ballad?", "A dark, thin ride with brushes", ["A china", "A stack", "A splash only"], "Soft, dark sounds suit quiet music."], ["A “groove” on the drum kit is…", "A repeated pattern that sets the feel of the song", ["A drum solo", "A tuning method", "A cymbal brand"], "Most of a drummer’s job."]], "midix": [["MIDI stands for…", "Musical Instrument Digital Interface", ["Music Input Device Interface", "Modern Instrument Data In", "Multi Input Digital Instrument"], "A standard from 1983."], ["A MIDI note message contains…", "Which note, how hard (velocity) and when", ["The actual sound", "A recording of your voice", "Only the tempo"], "MIDI is instructions, not audio."], ["MIDI velocity ranges from…", "0 to 127", ["0 to 100", "1 to 10", "0 to 255"], "127 is the hardest hit."], ["Middle C is MIDI note number…", "60", ["0", "48", "64"], "C4 = 60 in most DAWs."], ["A MIDI channel lets you…", "Send different parts to different instruments on one cable", ["Change the key", "Record audio", "Tune guitars"], "There are 16 channels."], ["How many MIDI channels does a standard connection have?", "16", ["8", "32", "128"], "Numbered 1 to 16."], ["A CC (Continuous Controller) message sends…", "Values for knobs like mod wheel or sustain", ["Note pitches only", "Audio", "The song title"], "CC1 is the mod wheel, CC64 is sustain."], ["Quantising MIDI means…", "Snapping notes to the rhythmic grid", ["Making it louder", "Adding reverb", "Changing the key"], "Partial quantise keeps some human feel."], ["The piano roll is…", "An editor showing MIDI notes as bars on a grid", ["A real piano", "A mixer", "A file format"], "Pitch up the side, time along the bottom."], ["Pitch bend in MIDI…", "Smoothly raises or lowers the pitch", ["Changes the tempo", "Changes the instrument", "Mutes the note"], "Sent by the pitch wheel."], ["A MIDI controller keyboard…", "Sends MIDI but usually makes no sound by itself", ["Records audio", "Has no keys", "Is a speaker"], "It plays instruments inside your computer."], ["Changing the instrument on a MIDI track…", "Plays the same notes with a new sound", ["Deletes the notes", "Changes the rhythm", "Changes the key"], "Notes and sound are separate."], ["Humanising MIDI means…", "Adding small timing and velocity changes", ["Recording a human voice", "Making it robotic", "Quantising fully"], "Small variations sound more natural."], ["Note length in the piano roll controls…", "How long the note is held", ["How loud it is", "Its pitch", "Its instrument"], "Stretch the bar to hold longer."], ["A drum rack or kit in MIDI maps…", "Each drum sound to a different note", ["Each note to the same sound", "Audio to MIDI", "Chords to bass"], "C1 is often the kick."], ["MIDI over USB means…", "Sending MIDI data through a normal USB cable", ["Sending audio only", "Charging only", "A special 5-pin cable"], "Most modern controllers use USB."], ["A MIDI file (.mid) stores…", "Notes and timing, not sound", ["An MP3", "A video", "A sample library"], "Load it into any instrument."], ["Velocity-sensitive keys…", "Play louder or softer depending on how hard you press", ["Always play the same volume", "Change pitch", "Change tempo"], "More expressive playing."], ["Arpeggiators in MIDI…", "Turn held chords into patterns of single notes", ["Mix the song", "Record audio", "Tune vocals"], "Hold a chord, get a pattern."], ["MPE (MIDI Polyphonic Expression) lets each note…", "Have its own pitch bend and pressure", ["Play on one channel only", "Be silent", "Be audio"], "Used by expressive controllers like the Roli Seaboard."]], "brootsx": [["The 5th above A on the bass is…", "E", ["D", "C♯", "F"], "A, B, C♯, D, E."], ["On the bass, the 5th of a note on the E string is found…", "On the A string, two frets higher", ["On the same string, two frets lower", "On the G string, same fret", "One fret higher on the D string"], "The root–5th shape."], ["The octave above a note on the E string is…", "Two strings up and two frets higher", ["One string up, same fret", "Twelve strings up", "Three frets lower"], "The octave shape."], ["The 5th below a root on the A string is found…", "On the E string at the same fret", ["On the D string two frets up", "On the G string", "Five frets lower"], "Same fret, one string lower."], ["A “root–5th” bass line in C uses…", "C and G", ["C and F", "C and E", "C and A"], "C, D, E, F, G: G is the 5th."], ["A root–5th pattern is typical of…", "Country, folk and early rock and roll", ["Only jazz", "Only metal", "Only classical"], "The “boom-chick” bass."], ["If the chord is G and you play B in the bass, you’re playing…", "The 3rd", ["The root", "The 5th", "The 7th"], "G, A, B: B is the 3rd."], ["Playing the root on beat 1 of each chord change…", "Makes the chords clear to the listener", ["Clashes with the chords", "Is wrong in rock", "Changes the key"], "The bass defines the harmony."], ["A bass line moving from C to D with a C♯ in between uses…", "A chromatic passing note", ["A wrong note", "A slap", "A harmonic"], "Half steps lead smoothly between roots."], ["Eighth-note roots in rock are best played…", "Even and steady, locked to the hi-hat", ["As loud as possible only", "With swing always", "With long gaps"], "Steady pulse drives the band."], ["A “slash chord” like C/E tells the bass player to play…", "E", ["C", "G", "Nothing"], "The note after the slash is the bass note."], ["What is the 5th of D?", "A", ["G", "F♯", "B"], "D, E, F♯, G, A."], ["On a 4-string bass in standard tuning, the strings from low to high are…", "E A D G", ["E A D G B E", "B E A D", "G D A E"], "The same as the lowest four guitar strings, an octave lower."], ["The open A string on bass and the 5th fret on the E string are…", "The same note", ["An octave apart", "A 5th apart", "Different notes"], "Use either to tune."], ["The 12th fret on any bass string gives…", "The open note an octave higher", ["A 5th", "The same pitch as open", "A random note"], "Halfway along the string."]], "plh": [["A “bass note then chord” left hand in 4/4 often plays…", "Bass on 1 and 3, chords on 2 and 4", ["Chords on every eighth", "Nothing on 1", "Only bass on 4"], "Stride and country use it."], ["Rolling a left-hand chord from the bottom note up is called…", "Arpeggiating or rolling the chord", ["Pedalling", "Staccato", "Trilling"], "Written with a wavy line."], ["A “Latin tumbao” bass pattern often anticipates…", "Beat 3, landing on the “and” of 2", ["Beat 1 always", "Every sixteenth", "Nothing"], "The bass leans ahead of the beat."], ["Playing the left hand an octave lower makes it…", "Deeper, but can get muddy with full chords", ["Brighter", "Quieter", "Out of tune"], "Use open intervals low down."], ["A “10th” stretch in the left hand may need to be…", "Rolled if your hand can’t reach it", ["Avoided completely", "Played with the right hand always", "Played with the pedal only"], "Roll from bottom to top."], ["An “oom-pah” left hand is typical of…", "Marches, polkas and ragtime", ["Ambient music", "Heavy metal", "Plainchant"], "Bass on the beat, chord off the beat."], ["Ragtime left hands usually play…", "Alternating bass notes and chords in a march-like pattern", ["Constant trills", "Only whole notes", "Nothing"], "Scott Joplin’s rags are classic examples."], ["Left-hand octaves in a rock ballad add…", "Power to the chorus", ["Softness to the verse", "A key change", "Nothing"], "Save them for big moments."], ["A “drone” in the left hand under a melody gives…", "A folk or Celtic feel", ["A jazz feel", "A metal feel", "A rap feel"], "Bagpipes use drones."], ["If the left-hand part feels heavy, try…", "Playing fewer notes or moving it up", ["Adding more notes", "Using more pedal", "Playing louder"], "Thin it out."]]};for(const k in A){if(JB[k])JB[k].push(...A[k]);else JB[k]=A[k]}
 const addSrc=(t,src)=>{if(JT[t]&&!JT[t][2].some(x=>x[0]===src))JT[t][2].push([src,1])};addSrc('midi','b:midix');addSrc('broots','b:brootsx')})();
